select a.id, a.account_type, count(t.id) as transaction_count, min(t.txn_time) as first_txn_time, round((100 * sum(case when t.merchant = 'Starbucks' then 1 else 0 end)) / count(*), 1) as pct_starbucks from accounts a join transactions t on a.id = t.account_id group by a.id, a.account_type having round((100 * sum(case when t.merchant = 'Starbucks' then 1 else 0 end)) / count(*), 1) > 74;
